/**
 * Retrieves a list of pages that match the specified prefix and are not redirects.
 *
 * @param string $prefix The prefix to match for page titles.
 * @return array An array of page titles that match the prefix and are not redirects.
 */
public function getWishesByPrefix( $prefix ) {
    $prefix = trim( $prefix );
    $excludePrefix = str_replace( ' ', '_', $prefix );

    $dbr = wfGetDB( DB_REPLICA );
    $query = $dbr->select(
        'page',
        'page_title',
        [
            'page_namespace' => NS_COMMUNITY_WISHLIST,
            'page_is_redirect' => 0,
            'page_title NOT REGEXP' => $excludePrefix . "[[:digit:]]+"
        ],
        __METHOD__,
        [],
        [
            'ORDER BY' => 'page_id'
        ]
    );

    $wishes = [];
    foreach ( $query as $row ) {
        $wishes[] = $row->page_title;
    }

    return $wishes;
}
