 *
 * @param array $params The UTM parameters.
 * @return string The type of traffic.
 */
function determineTrafficType(array $params): string {
    $utm_medium = $params['utm_medium'] ?? '';
    $utm_campaign = $params['utm_campaign'] ?? '';
    $direct_mail_appeal = $params['direct_mail_appeal'] ?? '';
    $channel = $params['channel'] ?? '';
    $utm_source = $params['utm_source'] ?? '';

    if ($utm_medium === 'portal' && $utm_campaign === 'portalBanner') {
        return 'portal banner';
    } elseif ($utm_medium === 'portal') {
        return 'other portal';
    }

    return '';
}
