    $services = $this->getServiceContainer();
    $wikiPage = $services->getWikiPageFactory()->newFromTitle(Title::newFromText($title));
    $content = $wikiPage->getContent();
    if ($content instanceof TextContent) {
        $text = $content->getText();
        $sections = MediaWikiServices::getInstance()->getSectionHelper()->splitSections($text);
