/**
 * Clones statements while preserving qualifiers and references.
 * @param {Object} entity - The entity containing the statements.
 * @param {string} propertyId - The property ID for which to clone statements.
 * @returns {Array} - The cloned statements with qualifiers and references preserved.
 */
function cloneStatementsWithQualifiersAndReferences(entity, propertyId) {
    if (!entity || !entity.claims || !entity.claims[propertyId]) {
        return [];
    }

    const originalStatements = entity.claims[propertyId];
    const cloneOfStatements = mw.clone(originalStatements);

    for (let i = 0; i < cloneOfStatements.length; i++) {
        cloneOfStatements[i].qualifiers = originalStatements[i].qualifiers;
        cloneOfStatements[i].references = originalStatements[i].references;
    }

    return cloneOfStatements;
}

