private function getMessageKey(?int $centralUserId, int $privateParticipantCount): string {
    if ($centralUserId) {
        // Check if the current user is a private participant
        $isPrivateParticipant = $this->participantsStore->isPrivateParticipant($centralUserId);
        if ($isPrivateParticipant) {
            // Check if there are other private participants that the user can't see
            $otherPrivateParticipantsCount = $privateParticipantCount - 1;
            if ($otherPrivateParticipantsCount > 0) {
                return 'campaignevents-contributions-notice-other-private-participants-excluded';
            } else {
                return 'campaignevents-contributions-notice-private-participants-excluded';
            }
        } else {
            return 'campaignevents-contributions-notice-private-participants-excluded';
        }
    } else {
        return 'campaignevents-contributions-notice-private-participants-excluded';
    }
